mapper.update:
UPDATE warehouse_stock
SET min_stock_quantity = #{minStockQuantity}
WHERE tenant_id = #{tenantId}
AND id = #{id}

mapper.select:
SELECT s.id, s.tenant_id, s.warehouse_id, w.site_id, w.warehouse_code, w.name AS warehouse_name, w.enabled AS warehouse_enabled, s.spare_part_id, p.part_code, p.name AS part_name, p.spec, p.unit, p.enabled AS spare_part_enabled, s.quantity, s.min_stock_quantity, CASE WHEN s.quantity < s.min_stock_quantity THEN 1 ELSE 0 END AS low_stock, s.created_at, s.updated_at FROM warehouse_stock s INNER JOIN warehouses w ON w.id = s.warehouse_id AND w.tenant_id = s.tenant_id INNER JOIN spare_parts p ON p.id = s.spare_part_id AND p.tenant_id = s.tenant_id WHERE s.tenant_id = #{tenantId}
AND s.warehouse_id = #{query.warehouseId}
AND s.spare_part_id = #{query.sparePartId}
AND (p.part_code LIKE CONCAT('%', #{keyword}, '%') OR p.name LIKE CONCAT('%', #{keyword}, '%'))
AND s.quantity < s.min_stock_quantity
ORDER BY s.warehouse_id ASC, s.spare_part_id ASC, s.id ASC

SELECT w.id AS warehouse_id, w.enabled AS warehouse_enabled,
       s.id AS site_id, s.enabled AS site_enabled
FROM warehouses w
LEFT JOIN sites s ON s.id = w.site_id AND s.tenant_id = w.tenant_id
WHERE w.tenant_id = #{tenantId}
  AND w.id = #{warehouseId}

SELECT enabled FROM spare_parts
WHERE tenant_id = #{tenantId}
  AND id = #{sparePartId}
